func smPtsQuad(pa *port.Cells, pts *port.Cells, r int32) int32 {
	// 1 when path row r is a closed quadrilateral: four corners, joined by lines (the fifth point repeats the first or is its `close`).
	var n int32 = evidence.PaGet(pa, r, evidence.PfPcount())
	var f int32 = evidence.PaGet(pa, r, evidence.PfPfirst())
	var j int32 = 0
	var op int32 = 0
	var corners int32 = 0
	if f < 0 {
		return 0
	}
	if (n < 4) || (n > 6) {
		return 0
	}
	for j < n {
		op = evidence.PtGet(pts, f+j, evidence.PtfOp())
		if op == evidence.PoCurve() {
			return 0
		}
		if (op == evidence.PoMove()) || (op == evidence.PoLine()) {
			corners += 1
		}
		j += 1
	}
	if (corners == 4) || (corners == 5) {
		return 1
	}
	return 0
}

func smStrokeOnly(pa *port.Cells, r int32) int32 {
	// 1 when path row r is stroked and neither filled nor a clip.
	var fl int32 = evidence.PaGet(pa, r, evidence.PfFlags())
	if (fl & evidence.PgStroked()) == 0 {
		return 0
	}
	if (fl & evidence.PgFilled()) != 0 {
		return 0
	}
	if (fl & evidence.PgClip()) != 0 {
		return 0
	}
	return 1
}

